changeSet.sql:
UPDATE parser
SET notes = CONCAT(IFNULL(notes, ''), ' Historique long (anciens de plus de 12 mois) : possible avec monthsAfterEnd > 12 et un contrôle des décès par le fichier INSEE (service deces.matchid.io). Renseigner deathCheckToken (jeton du service, dans la configuration du parser, jamais dans le dépôt) ; sans jeton, le quota anonyme s''épuise et les anciens non vérifiés ne sont pas publiés. Liste HATVP : seuls les membres en fonction y figurent, l''historique des ministres vient du Journal officiel (fr_pep_jorf).')
WHERE dataset_name = 'fr_pep_government';

UPDATE parser
SET notes = CONCAT(IFNULL(notes, ''), ' Historique long (anciens de plus de 12 mois) : possible avec monthsAfterEnd > 12, previousTermUrls (listes des législatures 9, 8… séparées par des espaces) et un contrôle des décès par le fichier INSEE (service deces.matchid.io). Renseigner deathCheckToken (jeton du service, dans la configuration du parser, jamais dans le dépôt) ; sans jeton, le quota anonyme s''épuise et les anciens non vérifiés ne sont pas publiés. Compter environ 1 appel par ancien député, avec 700 ms entre deux appels au Parlement européen (limite de débit).')
WHERE dataset_name = 'fr_pep_europarl';
